complexity_estimator_v5.code:
def complexity_estimator_v5(text):
    t = str(text)
    words = t.split()
    n = len(words)
    if n == 0:
        return {'load': 0.0, 'level': 'light'}
    long_words = sum(1 for w in words if len(w) >= 9)
    clauses = t.count(',') + t.count(';') + t.count(' and ') + t.count(' because ') + t.count(' which ')
    questions = t.count('?')
    score = n / 40.0 + long_words / n + clauses / 8.0 + questions / 4.0
    load = round(min(1.0, score / 2.0), 2)
    level = 'heavy' if load >= 0.6 else ('moderate' if load >= 0.3 else 'light')
    return {'load': load, 'level': level}

